'use strict';

const path = require('path');
const { openDatabase } = require('./db');
const { baueApp } = require('./lib/appFactory');
const auth = require('./lib/auth');
const benutzerSvc = require('./services/benutzer');

const PORT = process.env.PORT || 8080;
const HOST = '0.0.0.0';
const DB_PATH = process.env.DB_PATH || path.join(__dirname, 'data', 'hausverwaltung.db');
const UPLOAD_DIR = process.env.UPLOAD_DIR || path.join(__dirname, 'data', 'uploads');

/**
 * Legt beim allerersten Start einen Administrator an, damit man sich anmelden
 * kann. Zugangsdaten kommen aus der Projekt-Konfiguration (Secrets & Variables):
 *   ADMIN_BENUTZER   (Standard: admin)
 *   ADMIN_PASSWORT   (Standard: einmalig zufällig, wird in stdout protokolliert)
 * Das Standardpasswort sollte nach dem ersten Login geändert werden.
 */
async function seedAdmin(db) {
  const anzahl = await db.get('SELECT COUNT(*) AS n FROM benutzer');
  if (anzahl.n > 0) return;
  const benutzername = (process.env.ADMIN_BENUTZER || 'admin').toLowerCase();
  let passwort = process.env.ADMIN_PASSWORT;
  let generiert = false;
  if (!passwort) {
    passwort = require('crypto').randomBytes(9).toString('base64').replace(/[/+=]/g, 'x');
    generiert = true;
  }
  await benutzerSvc.anlegen(db, {
    benutzername,
    passwort,
    name: 'Administrator',
    rolle: 'admin',
  });
  console.log('[SETUP] Administrator angelegt. Benutzername:', benutzername);
  if (generiert) {
    console.log('[SETUP] Generiertes Start-Passwort (bitte nach Login ändern):', passwort);
    console.log('[SETUP] Für ein festes Passwort ADMIN_PASSWORT in der Projekt-Konfiguration setzen.');
  }
}

async function main() {
  const db = await openDatabase(DB_PATH);
  await auth.abgelaufeneEntfernen(db);
  await seedAdmin(db);

  const app = baueApp(db, { uploadDir: UPLOAD_DIR });
  app.listen(PORT, HOST, () => {
    console.log(`[START] Hausverwaltung läuft auf http://${HOST}:${PORT}`);
  });
}

main().catch((err) => {
  console.error('[FATAL] Start fehlgeschlagen:', err && err.stack ? err.stack : err);
  process.exit(1);
});
'use strict';

const express = require('express');
const cookieParser = require('cookie-parser');
const path = require('path');
const fs = require('fs');

const auth = require('./auth');
const { ValidationError } = require('./validation');
const { baueApi } = require('../routes/api');

// Vorschau-Bridge (siehe /.ai4-preview-bootstrap.js unten).
const VORSCHAU_SKRIPT = `(function () {
  async function melden() {
    try {
      var r = await fetch('/.ai4-preview-revision.json', { cache: 'no-store' });
      if (!r.ok) return;
      var d = await r.json();
      var rev = String((d && d.revision) != null ? d.revision : '');
      if (!rev) return;
      var m = document.querySelector('meta[name="ai4-preview-revision"]');
      if (m) m.setAttribute('content', rev);
      if (window.parent && window.parent !== window) window.parent.postMessage({ type: 'ai4-preview-ready', revision: rev }, '*');
    } catch (e) { /* Vorschau ist optional */ }
  }
  if (document.readyState === 'complete') melden(); else window.addEventListener('load', melden);
})();
`;

/**
 * Baut die Express-App. db und uploadDir werden injiziert, damit dieselbe
 * App auch in Tests mit einer In-Memory-Datenbank betrieben werden kann.
 */
function baueApp(db, options = {}) {
  const uploadDir = options.uploadDir || path.join(__dirname, '..', 'data', 'uploads');
  const publicDir = options.publicDir || path.join(__dirname, '..', 'public');
  const revisionDatei = options.revisionDatei || path.join(__dirname, '..', '.ai4', 'preview-revision.json');

  const app = express();
  app.disable('x-powered-by');
  app.use(express.json({ limit: '2mb' }));
  app.use(express.urlencoded({ extended: false }));
  app.use(cookieParser());
  app.use(auth.middleware(db));

  // API
  app.use('/api', baueApi(db, uploadDir));
  app.use('/api', (req, res) => res.status(404).json({ fehler: 'Unbekannte Schnittstelle.' }));

  // Vorschau-Aktualität (Plattform-Vertrag): Da Express alle Pfade bedient,
  // liefern wir die Helfer selbst aus – sonst fiele die SPA-Rückfallseite (HTML)
  // auf diese Pfade und das Vorschau-Skript bräche mit einem Syntaxfehler ab.
  app.get('/.ai4-preview-revision.json', (req, res) => {
    res.set('Cache-Control', 'no-store');
    fs.readFile(revisionDatei, 'utf8', (err, inhalt) => {
      let revision = '0';
      if (!err) { try { revision = String(JSON.parse(inhalt).revision ?? '0'); } catch (e) { /* Standard */ } }
      res.json({ revision });
    });
  });
  app.get('/.ai4-preview-bootstrap.js', (req, res) => {
    res.set('Cache-Control', 'no-store');
    res.type('application/javascript').send(VORSCHAU_SKRIPT);
  });

  // Statische Oberfläche
  app.use(express.static(publicDir, { extensions: ['html'] }));

  // SPA-Fallback: unbekannte, nicht-API GET-Routen liefern die App-Shell.
  app.get(/^(?!\/api\/).*/, (req, res, next) => {
    if (req.method !== 'GET') return next();
    res.sendFile(path.join(publicDir, 'index.html'));
  });

  // Zentraler Fehler-Handler (deutsche Meldungen, saubere Statuscodes).
  // eslint-disable-next-line no-unused-vars
  app.use((err, req, res, next) => {
    if (err instanceof ValidationError) {
      return res.status(err.status || 400).json({ fehler: err.message });
    }
    if (err && err.code === 'LIMIT_FILE_SIZE') {
      return res.status(413).json({ fehler: 'Datei zu groß (Archiv max. 50 MB, Plaud-Aufnahmen max. 95 MB).' });
    }
    if (err && err.type === 'entity.too.large') {
      return res.status(413).json({ fehler: 'Anfrage zu groß.' });
    }
    // Unerwartete Fehler in stderr protokollieren (Diagnostik-Contract).
    console.error('[FEHLER]', err && err.stack ? err.stack : err);
    res.status(500).json({ fehler: 'Interner Serverfehler.' });
  });

  return app;
}

module.exports = { baueApp };
'use strict';

const sqlite3 = require('sqlite3');
const fs = require('fs');
const path = require('path');

/**
 * Dünner Promise-Wrapper um node-sqlite3.
 * Auf dieser Plattform wird bewusst das `sqlite3`-Paket (nicht better-sqlite3)
 * verwendet und journal_mode=DELETE gesetzt, da /app auf gemeinsam genutztem
 * Speicher liegt und WAL-Locking dort fragil sein kann.
 *
 * Alle Anfragen laufen über eine Verbindung. Damit eine Transaktion keine
 * Anweisungen paralleler HTTP-Anfragen „einsammelt" (und bei ROLLBACK mit
 * verwirft), werden Anweisungen nacheinander abgearbeitet; transaktion()
 * hält die Warteschlange bis COMMIT/ROLLBACK exklusiv.
 */
class Database {
  constructor(dbInstance) {
    this.db = dbInstance;
    this._warteschlange = Promise.resolve();
  }

  _exklusiv(fn) {
    const p = this._warteschlange.then(fn, fn);
    this._warteschlange = p.catch(() => {});
    return p;
  }

  _run(sql, params = []) {
    return new Promise((resolve, reject) => {
      this.db.run(sql, params, function (err) {
        if (err) return reject(err);
        resolve({ lastID: this.lastID, changes: this.changes });
      });
    });
  }

  _get(sql, params = []) {
    return new Promise((resolve, reject) => {
      this.db.get(sql, params, (err, row) => (err ? reject(err) : resolve(row)));
    });
  }

  _all(sql, params = []) {
    return new Promise((resolve, reject) => {
      this.db.all(sql, params, (err, rows) => (err ? reject(err) : resolve(rows || [])));
    });
  }

  _execRoh(sql) {
    return new Promise((resolve, reject) => {
      this.db.exec(sql, (err) => (err ? reject(err) : resolve()));
    });
  }

  run(sql, params) { return this._exklusiv(() => this._run(sql, params)); }
  get(sql, params) { return this._exklusiv(() => this._get(sql, params)); }
  all(sql, params) { return this._exklusiv(() => this._all(sql, params)); }
  exec(sql) { return this._exklusiv(() => this._execRoh(sql)); }

  /**
   * Führt fn(tx) atomar aus. tx hat dieselbe Schnittstelle (run/get/all);
   * innerhalb von fn ausschließlich tx verwenden, nicht db (sonst Deadlock).
   */
  transaktion(fn) {
    return this._exklusiv(async () => {
      const tx = {
        run: (s, p) => this._run(s, p),
        get: (s, p) => this._get(s, p),
        all: (s, p) => this._all(s, p),
        exec: (s) => this._execRoh(s),
      };
      await this._run('BEGIN IMMEDIATE');
      try {
        const ergebnis = await fn(tx);
        await this._run('COMMIT');
        return ergebnis;
      } catch (e) {
        await this._run('ROLLBACK').catch(() => {});
        throw e;
      }
    });
  }

  close() {
    return this._exklusiv(
      () => new Promise((resolve, reject) => this.db.close((err) => (err ? reject(err) : resolve())))
    );
  }
}

/**
 * Öffnet (oder erstellt) die Datenbank, wendet das Schema an und migriert
 * ältere Datenbestände (siehe db/migrate.js).
 * @param {string} filePath  Pfad zur SQLite-Datei oder ':memory:'
 */
async function openDatabase(filePath) {
  if (filePath !== ':memory:') {
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
  }
  const raw = await new Promise((resolve, reject) => {
    const inst = new sqlite3.Database(filePath, (err) => (err ? reject(err) : resolve(inst)));
  });
  const db = new Database(raw);
  // Gemeinsamer Speicher: DELETE-Journal statt WAL (siehe Plattform-Hinweis).
  await db.run('PRAGMA journal_mode = DELETE');
  await db.run('PRAGMA foreign_keys = ON');
  const schema = fs.readFileSync(path.join(__dirname, 'schema.sql'), 'utf8');
  await db.exec(schema);
  await require('./migrate').migrieren(db, filePath);
  return db;
}

module.exports = { Database, openDatabase };
'use strict';

const path = require('path');
const N = require('../lib/nummern');

async function spalten(db, tabelle) {
  const rows = await db.all(`PRAGMA table_info(${tabelle})`);
  return new Set(rows.map((r) => r.name));
}

/**
 * Bringt ältere Datenbanken auf den aktuellen Stand. Jeder Schritt prüft
 * selbst, ob er nötig ist, und kann daher beliebig oft laufen.
 *
 * v1 → v2:
 *  - Spalte `nummer` für Objekte (aus interne_nr übernommen), Einheiten und
 *    Adressen; fehlende Nummern werden automatisch vergeben.
 *  - Dokumente werden zum zentralen Archiv: Bezüge (objekt_id/einheit_id)
 *    wandern in archiv_verknuepfungen, damit ein Eintrag beliebig vielen
 *    Objekten, Einheiten und Adressen zugeordnet werden kann.
 */
async function migrieren(db, filePath) {
  const sObjekte = await spalten(db, 'objekte');
  const sEinheiten = await spalten(db, 'einheiten');
  const sAdressen = await spalten(db, 'adressen');
  const sDokumente = await spalten(db, 'dokumente');

  const dokAltesFormat = sDokumente.has('objekt_id');
  const brauchtSpalten = !sObjekte.has('nummer') || !sEinheiten.has('nummer') || !sAdressen.has('nummer')
    || !sAdressen.has('geburtstag') || !sAdressen.has('ampel') || !sAdressen.has('versand_standard')
    || !sObjekte.has('objekt_art');

  if ((dokAltesFormat || brauchtSpalten) && filePath && filePath !== ':memory:') {
    // Konsistente Sicherung vor dem Umbau.
    const stempel = new Date().toISOString().replace(/[:.]/g, '-');
    const ziel = path.join(path.dirname(filePath), `sicherung-vor-migration-${stempel}.db`);
    await db.run('VACUUM INTO ?', [ziel]);
    console.log('[MIGRATION] Sicherung erstellt:', ziel);
  }

  // ---- 1) Nummern-Spalten ---------------------------------------------
  if (!sObjekte.has('nummer')) await db.run('ALTER TABLE objekte ADD COLUMN nummer TEXT');
  if (!sEinheiten.has('nummer')) await db.run('ALTER TABLE einheiten ADD COLUMN nummer TEXT');
  if (!sAdressen.has('nummer')) await db.run('ALTER TABLE adressen ADD COLUMN nummer TEXT');

  // Fehlende Objekt-Nummern: vorhandene interne_nr übernehmen, sonst automatisch.
  const objOhne = await db.all('SELECT * FROM objekte WHERE nummer IS NULL ORDER BY id');
  for (const o of objOhne) {
    let nr = null;
    if (o.interne_nr) {
      try {
        const kandidat = N.pruefeNummer(o.interne_nr, 'Objekt-Nr.');
        const belegt = await db.get('SELECT 1 FROM objekte WHERE nummer = ? COLLATE NOCASE', [kandidat]);
        if (!belegt) nr = kandidat;
      } catch (e) { /* ungültig → automatisch */ }
    }
    if (!nr) nr = await N.naechsteObjektNr(db);
    await db.run('UPDATE objekte SET nummer = ? WHERE id = ?', [nr, o.id]);
  }
  const einhOhne = await db.all('SELECT id, objekt_id FROM einheiten WHERE nummer IS NULL ORDER BY objekt_id, id');
  for (const e of einhOhne) {
    await db.run('UPDATE einheiten SET nummer = ? WHERE id = ?', [await N.naechsteEinheitNr(db, e.objekt_id), e.id]);
  }
  const adrOhne = await db.all('SELECT id FROM adressen WHERE nummer IS NULL ORDER BY id');
  for (const a of adrOhne) {
    await db.run('UPDATE adressen SET nummer = ? WHERE id = ?', [await N.naechsteAdressNr(db), a.id]);
  }

  await db.exec(`
    CREATE UNIQUE INDEX IF NOT EXISTS ux_objekte_nummer   ON objekte(nummer COLLATE NOCASE);
    CREATE UNIQUE INDEX IF NOT EXISTS ux_einheiten_nummer ON einheiten(nummer COLLATE NOCASE);
    CREATE UNIQUE INDEX IF NOT EXISTS ux_adressen_nummer  ON adressen(nummer COLLATE NOCASE);
  `);

  // ---- 1b) Adressen: Geburtstag, LKto-Nr., Datenschutz -----------------
  for (const spalte of ['geburtstag', 'lkto_nr', 'datenschutz_datum', 'ampel', 'ampel_notiz', 'ampel_datum', 'zusatz']) {
    if (!sAdressen.has(spalte)) await db.run(`ALTER TABLE adressen ADD COLUMN ${spalte} TEXT`);
  }
  if (!sAdressen.has('datenschutz_zustimmung')) {
    await db.run('ALTER TABLE adressen ADD COLUMN datenschutz_zustimmung TEXT');
    // bisher erfasstes Einwilligungsdatum gilt als Zustimmung
    await db.run("UPDATE adressen SET datenschutz_zustimmung = 'ja' WHERE datenschutz_datum IS NOT NULL");
  }
  if (!sAdressen.has('versand_standard')) await db.run("ALTER TABLE adressen ADD COLUMN versand_standard TEXT NOT NULL DEFAULT 'post'");
  if (!sAdressen.has('ampel_von')) await db.run('ALTER TABLE adressen ADD COLUMN ampel_von INTEGER REFERENCES benutzer(id) ON DELETE SET NULL');

  // ---- 1b') Objekte: Felder der HausPerfekt-Objektmaske --------------------
  for (const spalte of ['objekt_art', 'buero_kst', 'gruppe1', 'gruppe2', 'gruppe3', 'gruppe4', 'gruppe5',
    'heizungsart', 'warmwasser', 'garagenart', 'muellgefaesse']) {
    if (!sObjekte.has(spalte)) await db.run(`ALTER TABLE objekte ADD COLUMN ${spalte} TEXT`);
  }
  for (const spalte of ['anzahl_gebaeude', 'anzahl_eingaenge']) {
    if (!sObjekte.has(spalte)) await db.run(`ALTER TABLE objekte ADD COLUMN ${spalte} INTEGER`);
  }
  if (!sObjekte.has('sachbearbeiter_id')) await db.run('ALTER TABLE objekte ADD COLUMN sachbearbeiter_id INTEGER REFERENCES benutzer(id) ON DELETE SET NULL');
  if (!sObjekte.has('verkauf')) await db.run('ALTER TABLE objekte ADD COLUMN verkauf INTEGER NOT NULL DEFAULT 1');
  if (!sObjekte.has('vermietung')) await db.run('ALTER TABLE objekte ADD COLUMN vermietung INTEGER NOT NULL DEFAULT 1');

  // ---- 1b'') Sachkonten: Abrechnungsangaben aus dem HausPerfekt-Import -------
  const sSachkonten = await spalten(db, 'sachkonten');
  for (const spalte of ['vs_eg', 'vs_mi', 'hp_attribute']) {
    if (sSachkonten.size && !sSachkonten.has(spalte)) await db.run(`ALTER TABLE sachkonten ADD COLUMN ${spalte} TEXT`);
  }

  // ---- 1b''') Personenfunktion: HausPerfekt-Code (001, 002 …) ------------------
  const sZuord = await spalten(db, 'rollen_zuordnungen');
  if (!sZuord.has('pfkt_code')) await db.run('ALTER TABLE rollen_zuordnungen ADD COLUMN pfkt_code TEXT REFERENCES pfkt_codes(code)');

  // ---- 1b'''') Personenfunktions-Codes: Kennzeichen + HausPerfekt-Schlüsseltabelle (einmalig) ------
  const sCodes = await spalten(db, 'pfkt_codes');
  if (!sCodes.has('kennz')) await db.run('ALTER TABLE pfkt_codes ADD COLUMN kennz TEXT');

  // ---- 1c) Kontaktprotokoll: Zusatzinformationen fürs ZIS ----------------
  const sKontakte = await spalten(db, 'kontakte');
  if (!sKontakte.has('intern')) await db.run('ALTER TABLE kontakte ADD COLUMN intern INTEGER NOT NULL DEFAULT 0');
  if (!sKontakte.has('minuten')) await db.run('ALTER TABLE kontakte ADD COLUMN minuten INTEGER');
  if (!sKontakte.has('objekt_id')) await db.run('ALTER TABLE kontakte ADD COLUMN objekt_id INTEGER REFERENCES objekte(id) ON DELETE SET NULL');
  for (const [spalte, typ] of [['eingang', 'INTEGER NOT NULL DEFAULT 0'], ['anrufer_adresse_id', 'INTEGER REFERENCES adressen(id) ON DELETE SET NULL'],
    ['anrufer_name', 'TEXT'], ['rueckruf_tel', 'TEXT'], ['pfkt_code', 'TEXT'], ['erledigt', 'INTEGER NOT NULL DEFAULT 1'],
    ['rueckruf_sb_id', 'INTEGER REFERENCES benutzer(id) ON DELETE SET NULL'], ['team', 'TEXT'], ['zis', 'INTEGER NOT NULL DEFAULT 1'],
    ['aufnahme', 'TEXT'], ['aufnahme_zustimmung', 'INTEGER NOT NULL DEFAULT 0']]) {
    if (sKontakte.size && !sKontakte.has(spalte)) await db.run(`ALTER TABLE kontakte ADD COLUMN ${spalte} ${typ}`);
  }
  if (!sKontakte.has('einheit_id')) await db.run('ALTER TABLE kontakte ADD COLUMN einheit_id INTEGER REFERENCES einheiten(id) ON DELETE SET NULL');

  // ---- 2) Dokumente → zentrales Archiv ----------------------------------
  if (dokAltesFormat) {
    // Tabellen-Neuaufbau nach SQLite-Empfehlung; FKs dafür kurz aus.
    await db.run('PRAGMA foreign_keys = OFF');
    try {
      await db.transaktion(async (tx) => {
        await tx.exec(`
          CREATE TABLE dokumente_neu (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            titel           TEXT NOT NULL,
            kategorie       TEXT NOT NULL DEFAULT 'sonstiges',
            beschreibung    TEXT,
            dokument_datum  TEXT,
            original_name   TEXT NOT NULL,
            speicher_name   TEXT NOT NULL,
            mime_type       TEXT,
            groesse         INTEGER,
            quelle          TEXT NOT NULL DEFAULT 'upload',
            hochgeladen_von INTEGER REFERENCES benutzer(id) ON DELETE SET NULL,
            erstellt_am     TEXT NOT NULL DEFAULT (datetime('now'))
          );
          INSERT INTO dokumente_neu (id, titel, kategorie, beschreibung, original_name, speicher_name,
                                     mime_type, groesse, quelle, hochgeladen_von, erstellt_am)
            SELECT id, titel, kategorie, beschreibung, original_name, speicher_name,
                   mime_type, groesse, quelle, hochgeladen_von, erstellt_am FROM dokumente;
          INSERT OR IGNORE INTO archiv_verknuepfungen (dokument_id, objekt_id)
            SELECT id, objekt_id FROM dokumente WHERE objekt_id IS NOT NULL;
          INSERT OR IGNORE INTO archiv_verknuepfungen (dokument_id, einheit_id)
            SELECT id, einheit_id FROM dokumente WHERE einheit_id IS NOT NULL;
          DROP TABLE dokumente;
          ALTER TABLE dokumente_neu RENAME TO dokumente;
        `);
        const fehler = await tx.all('PRAGMA foreign_key_check');
        if (fehler.length) throw new Error('Fremdschlüsselprüfung nach Migration fehlgeschlagen');
      });
      console.log('[MIGRATION] Dokumente in zentrales Archiv überführt.');
    } finally {
      await db.run('PRAGMA foreign_keys = ON');
    }
  }

  // ---- 3) Einmalig: telefon/mobil/email in die Kommunikationslisten übernehmen
  const { user_version: version } = await db.get('PRAGMA user_version');
  if (version < 3) {
    const adressen = await db.all('SELECT id FROM adressen');
    const kommunikation = require('../services/kommunikation');
    for (const a of adressen) await kommunikation.uebernehmenAusStamm(db, a.id);
    await db.run('PRAGMA user_version = 3');
    if (adressen.length) console.log(`[MIGRATION] Kontaktdaten von ${adressen.length} Adresse(n) in Telefon-/E-Mail-Listen übernommen.`);
  }

  // ---- 3b) Einmalig: Schlüsseltabelle PFkt aus HausPerfekt (340 Codes) übernehmen
  const { user_version: v4 } = await db.get('PRAGMA user_version');
  if (v4 < 4) {
    const { codes } = require('../services/pfktCodesHausPerfekt.json');
    await db.transaktion(async (tx) => {
      for (const [code, bezeichnung, kennz, rolle] of codes) {
        await tx.run(`INSERT INTO pfkt_codes (code, bezeichnung, rolle, kennz) VALUES (?,?,?,?)
          ON CONFLICT(code) DO UPDATE SET bezeichnung = excluded.bezeichnung, rolle = excluded.rolle, kennz = excluded.kennz`, [code, bezeichnung, rolle, kennz]);
      }
    });
    await db.run('PRAGMA user_version = 4');
    if (filePath && filePath !== ':memory:') console.log(`[MIGRATION] ${codes.length} Personenfunktions-Codes aus HausPerfekt übernommen.`);
  }
}

module.exports = { migrieren };
'use strict';

const crypto = require('crypto');

const COOKIE_NAME = 'hv_session';
const SESSION_TAGE = 7;

function neuerToken() {
  return crypto.randomBytes(32).toString('hex');
}

function ablaufDatum() {
  const d = new Date();
  d.setDate(d.getDate() + SESSION_TAGE);
  return d.toISOString();
}

/** Erstellt eine Sitzung und gibt das Token zurück. */
async function sitzungErstellen(db, benutzerId) {
  const token = neuerToken();
  await db.run(
    'INSERT INTO sitzungen (token, benutzer_id, ablauf_am) VALUES (?,?,?)',
    [token, benutzerId, ablaufDatum()]
  );
  return token;
}

async function sitzungLoeschen(db, token) {
  if (!token) return;
  await db.run('DELETE FROM sitzungen WHERE token = ?', [token]);
}

/** Löscht abgelaufene Sitzungen (Wartung). */
async function abgelaufeneEntfernen(db) {
  await db.run("DELETE FROM sitzungen WHERE ablauf_am < datetime('now')");
}

async function benutzerAusSitzung(db, token) {
  if (!token) return null;
  const s = await db.get(
    "SELECT * FROM sitzungen WHERE token = ? AND ablauf_am > datetime('now')",
    [token]
  );
  if (!s) return null;
  const b = await db.get('SELECT * FROM benutzer WHERE id = ? AND aktiv = 1', [s.benutzer_id]);
  if (!b) return null;
  const { passwort_hash, ...rest } = b;
  return rest;
}

// Die App wird u. a. im 4everyone-Vorschau-iFrame (fremde Top-Level-Domain)
// angezeigt. Damit das Session-Cookie in diesem eingebetteten Kontext gesetzt
// und mitgesendet wird, muss es SameSite=None; Secure; Partitioned tragen.
// Da der Plattform-Ingress TLS terminiert (öffentliche URL ist HTTPS), ist
// Secure erfüllt. Über die Env-Variable COOKIE_INSECURE=1 lässt sich das für
// reine HTTP-Umgebungen (z. B. lokale Tests) abschalten.
const COOKIE_INSECURE = process.env.COOKIE_INSECURE === '1';
function cookieOptionen() {
  if (COOKIE_INSECURE) {
    return { httpOnly: true, sameSite: 'lax', secure: false, path: '/' };
  }
  return { httpOnly: true, sameSite: 'none', secure: true, partitioned: true, path: '/' };
}

/** Setzt das Session-Cookie (HttpOnly, kein Token in Query/JS-Zugriff nötig). */
function cookieSetzen(res, token) {
  res.cookie(COOKIE_NAME, token, {
    ...cookieOptionen(),
    maxAge: SESSION_TAGE * 24 * 60 * 60 * 1000,
  });
}

function cookieLoeschen(res) {
  res.clearCookie(COOKIE_NAME, cookieOptionen());
}

/** Express-Middleware: hängt req.benutzer an, wenn eingeloggt. */
function middleware(db) {
  return async (req, res, next) => {
    try {
      const token = req.cookies ? req.cookies[COOKIE_NAME] : null;
      req.sessionToken = token;
      req.benutzer = await benutzerAusSitzung(db, token);
    } catch (e) {
      req.benutzer = null;
    }
    next();
  };
}

/** Verlangt eine Anmeldung. */
function erfordereLogin(req, res, next) {
  if (!req.benutzer) {
    return res.status(401).json({ fehler: 'Nicht angemeldet.' });
  }
  next();
}

/** Verlangt Schreibrechte (admin oder mitarbeiter). "leser" darf nur lesen. */
function erfordereSchreibrecht(req, res, next) {
  if (!req.benutzer) return res.status(401).json({ fehler: 'Nicht angemeldet.' });
  if (req.benutzer.rolle === 'leser') {
    return res.status(403).json({ fehler: 'Keine Schreibberechtigung (nur Lesezugriff).' });
  }
  next();
}

/** Verlangt Administratorrechte. */
function erfordereAdmin(req, res, next) {
  if (!req.benutzer) return res.status(401).json({ fehler: 'Nicht angemeldet.' });
  if (req.benutzer.rolle !== 'admin') {
    return res.status(403).json({ fehler: 'Administratorrechte erforderlich.' });
  }
  next();
}

module.exports = {
  COOKIE_NAME,
  sitzungErstellen,
  sitzungLoeschen,
  abgelaufeneEntfernen,
  benutzerAusSitzung,
  cookieSetzen,
  cookieLoeschen,
  middleware,
  erfordereLogin,
  erfordereSchreibrecht,
  erfordereAdmin,
};
